/**
 * @method
 * @name scwin.init_pageBody
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_pageBody = function () {
    try {
        /* sdd-asis-lifecycle:begin onpageload — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        const pageIndex = $c.util.getComponent('ipt_currentPage').getValue();
        const pageObj = $('.paging td:contains(' + pageIndex + ')');
        const pagingLeng = $('.paging td:contains(' + pageIndex + ')').length;
        for (let i = 0; i < pagingLeng; i++) {
            const obj = pageObj[i];
            const val = $(obj).text();
            if (pageIndex !== val) {
                continue;
            }
            const font = "<font color='blue'>" + val + "</font>";
            $(obj).html(font);
            $(obj).attr("style", "font-size:15px;");
        }
        scwin.dateSetting();
        scwin.cgSearch((String((((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "ipt_curSh" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("ipt_curSh"))) == null ? '' : (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "ipt_curSh" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("ipt_curSh")))).indexOf('$' + '{') >= 0 ? '' : String((((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "ipt_curSh" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("ipt_curSh"))) == null ? '' : (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "ipt_curSh" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("ipt_curSh"))))), 'Y');
        $('input[name=ipt_isurNm1]').keypress(async function(e) {
                if (e.keyCode == 13) {
                    await scwin.search('1');
                }
        });
        $('input[name=rd_searchRadio]').bind("click", function() {
                $c.util.getComponent('ipt_curSh').setValue($(this).val());
                $('.paging').empty();
                const resetPaging = "<tr><td style='padding-left:5px'><img diabled src='/img/btn/btn-pprev.gif' alt=''></td><td style='padding-left:5px'><img src='/img/btn/btn-prev.gif' alt='' ></td><td class='bg_pagingbar'></td><td>1</td><td style='padding-left:5px'><img src='/img/btn/btn-next.gif' border='0' ></td><td style='padding-left:5px'><img src='/img/btn/btn-nnext.gif' alt='' ></a></td></tr>";
                $('.paging').append(resetPaging);
        });
        $c.util.getComponent("id_date").setStyle("display", "none");
        $c.util.getComponent("id_search").setStyle("display", "none");
        $c.util.getComponent("id_type").setStyle("display", "none");
        $c.util.getComponent("ipt_isurNm1").focus();
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldinf40000.onpageload' }); }
};

// [A] 초기 목록 미해결 — 진입 근거가 다른 액션을 가리킨다(srch vs excel) — 어느 쪽인지 정할 근거가 없다


// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
